/// The `upper` table for Unicode version `v` (code points from U+0080).
pub(super) fn upper(v: UnicodeVersion) -> &'static [(u32, u32)] {
    match v {
        UnicodeVersion::V14_0 | UnicodeVersion::V15_0 | UnicodeVersion::V15_1 => UPPER_V14_0,
        UnicodeVersion::V16_0 => UPPER_V16_0,
        UnicodeVersion::V17_0 => UPPER_V17_0,
    }
}

