/// The `lower` table for Unicode version `v` (code points from U+0080).
pub(super) fn lower(v: UnicodeVersion) -> &'static [(u32, u32)] {
    match v {
        UnicodeVersion::V14_0 => LOWER_V14_0,
        UnicodeVersion::V15_0 | UnicodeVersion::V15_1 => LOWER_V15_0,
        UnicodeVersion::V16_0 => LOWER_V16_0,
        UnicodeVersion::V17_0 => LOWER_V17_0,
    }
}

