/// The `digit` table for Unicode version `v` (code points from U+0080).
pub(super) fn digit(v: UnicodeVersion) -> &'static [(u32, u32)] {
    match v {
        UnicodeVersion::V14_0 => DIGIT_V14_0,
        UnicodeVersion::V15_0 | UnicodeVersion::V15_1 => DIGIT_V15_0,
        UnicodeVersion::V16_0 => DIGIT_V16_0,
        UnicodeVersion::V17_0 => DIGIT_V17_0,
    }
}
